INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/09/02/contre-tarifs-du-8-septembre-fenetre-de-gel-pour-les-spcc',
  'tax',
  'article',
  'Les contre-tarifs du 8 septembre ouvrent une fenêtre de gel pour les SPCC exposées aux États-Unis',
  'La compression des marges causée par le nouveau barème tarifaire peut abaisser assez longtemps la valeur d’une société privée pour justifier de revoir un gel successoral, et le prêt au taux prescrit qui le finance, avant le 8 septembre.',
  '<ul>
<li><strong>Les contre-tarifs canadiens entrent en vigueur le 8 septembre 2026, appliquant des taux de 15&nbsp;%, 25&nbsp;% et 50&nbsp;% à environ 27,6&nbsp;milliards de dollars d’importations américaines,</strong><span> en concordance dollar pour dollar avec les tarifs de l’article 338 américain.</span></li>
<li><strong>Dix des treize lignes tarifaires échantillonnées, dont les lingots d’acier, le contreplaqué et les intrants laitiers, se situent au taux maximal de 50&nbsp;%,</strong><span> le reste se situant à 25&nbsp;%.</span></li>
<li><strong>Les SPCC qui s’approvisionnent en intrants américains tarifés font face à une compression des marges à court terme,</strong><span> ce qui peut déprimer temporairement la valeur utilisée pour exécuter ou rafraîchir un gel successoral.</span></li>
<li><strong>Le taux prescrit de l’ARC se maintient à 3&nbsp;% pour un sixième trimestre consécutif jusqu’au T4 2026,</strong><span> ce qui garde les prêts aux fiducies familiales historiquement peu coûteux pour financer un gel.</span></li>
<li><strong>La fenêtre de planification est limitée dans le temps,</strong><span> puisque les valeurs se redressent une fois les chaînes d’approvisionnement ajustées, et le gel doit être documenté avant ce redressement, pas après.</span></li>
</ul>',
  '<p>Les contre-tarifs canadiens sur les produits américains entrent en vigueur à 0 h 01 le 8 septembre. Les mesures appliquent des taux de 15 %, 25 % et 50 % sur environ 27,6 milliards de dollars d’importations, en concordance dollar pour dollar avec les droits de douane de l’article 338 américain imposés aux produits canadiens en août. Pour une SPCC qui s’approvisionne en intrants tarifés aux États-Unis, l’effet immédiat est une hausse du coût des marchandises vendues. L’effet sur la planification est moins évident, mais plus utile.</p>
<h2>Ce que le barème tarifaire touche réellement</h2>
<p>Le barème des contre-tarifs penche fortement vers le taux le plus élevé. Sur un échantillon de treize lignes de produits touchées, couvrant les produits laitiers, la foresterie, l’acier et les biens de consommation, dix se situent à 50 % et les trois autres à 25 %.</p>
<div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
