INSERT OR REPLACE INTO articles
  (slug, desk, article_type, title, dek, brief_html, body_html, respond_html, prospect_html, key_numbers, hero_image, hero_caption, read_time, published_at, tags, toolkit_gated, sources_text, en_slug)
VALUES (
  '2026/09/02/prevision-croissance-bdc-07-conditionnalite-petrole',
  'economy',
  'article',
  'La prévision de 0,7 % de la Banque du Canada ne colle pas à un trimestre de 2,5 %, d’où le statu quo d’aujourd’hui',
  'Le gouverneur Macklem a lié le prochain mouvement de taux au prix du pétrole, une conditionnalité que les marchés n’intègrent presque pas.',
  '<ul>
<li><strong>La Banque du Canada devrait largement maintenir son taux directeur à 2,25&nbsp;% aujourd’hui,</strong><span> un septième maintien consécutif et la plus longue pause depuis la fin du cycle d’assouplissement en octobre 2025.</span></li>
<li><strong>Le PIB du T2 a crû à un rythme annualisé de 2,5&nbsp;%, pourtant la Banque a abaissé sa prévision de croissance pour 2026 à 0,7&nbsp;% contre 1,2&nbsp;%,</strong><span> ce qui sous-entend un net ralentissement attendu au second semestre.</span></li>
<li><strong>L’inflation globale a atteint 3,0&nbsp;% en juillet, et la Banque a révisé à la hausse sa prévision d’inflation pour 2026 à 2,5&nbsp;% contre 2,3&nbsp;%,</strong><span> en grande partie à cause des coûts énergétiques.</span></li>
<li><strong>Le gouverneur Macklem a dit que des hausses persistantes du prix du pétrole pourraient exiger des hausses de taux consécutives,</strong><span> tout en précisant que ce scénario n’est pas l’hypothèse de base de la Banque.</span></li>
<li><strong>Les marchés intègrent un peu plus de 2 points de base de resserrement additionnel d’ici la fin de l’année,</strong><span> ce qui laisse le scénario pétrolier largement non intégré s’il se concrétise.</span></li>
</ul>',
  '<p>La Banque du Canada devrait largement maintenir son taux directeur à 2,25 % aujourd’hui, son septième maintien consécutif et la plus longue période d’inaction depuis le cycle d’assouplissement qui a fait passer le taux de 3,00 % en janvier 2025 à son niveau actuel d’ici la fin octobre. En surface, un septième maintien se lit comme une histoire de stabilité. La prévision qui se cache derrière raconte une histoire plus compliquée.</p>
<h2>Une prévision de croissance qui ne colle pas à ses propres données</h2>
<p>L’historique du taux directeur de la Banque depuis janvier 2025 illustre la forme du problème : un cycle d’assouplissement rapide jusqu’en octobre, suivi de huit mois de stabilité à 2,25 %, alors que les perspectives de croissance sous-jacentes ont évolué dans le sens inverse des données affichées.</p>
<div class="hdq-chart">
<div style="background:#ffffff;border:1px solid #d0d0d0;width:100%;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;">
